-- | Pure Pattern action lowerings used by the generated structural parser.

import Data.List (..)

import Data.String (ends_with)

import Syntax.Source (..)

import Syntax.Ast (..)

import Syntax.Parse.Build (..)

import Syntax.Parse.Support (surface_float, surface_int)

pub fn pattern_int(raw : String, negative : Bool, span : Span) : Sp(Pat) =
  let n = str_len(raw)
  let (digits, suffix) =
    if ends_with("i64", raw) then
      (substring(raw, 0, n - 3), SufI64)
    elif ends_with("u64", raw) then
      (substring(raw, 0, n - 3), SufU64)
    else
      (raw, SufNone)
  let value = surface_int(digits)
  authored(
      PInt(if negative then concat("-", value) else value, suffix),
      span.lo,
      span.hi,
    )

pub fn pattern_float(raw : String, negative : Bool, span : Span) : Sp(Pat) =
  let value = surface_float(raw)
  authored(
      PFloat(if negative then concat("-", value) else value),
      span.lo,
      span.hi,
    )

pub fn pattern_list(items : List(Sp(Pat)), outer : Span) : Sp(Pat) =
  widened(
      pattern_list_tail(items, zero_width(PCtor("Nil", Nil), outer.hi)),
      outer.lo,
      outer.hi,
    )

fn pattern_list_tail(items : List(Sp(Pat)), rest : Sp(Pat)) : Sp(Pat) =
  match items of
    Nil => rest
    Cons(head, tail) =>
      authored(
          PCtor("Cons", [head, pattern_list_tail(tail, rest)]),
          head.span.lo,
          head.span.hi,
        )

defs.source:
fn fst(p) =
  match p of
    (x, _) => x

fn snd(p) =
  match p of
    (_, y) => y

fn swap(p) =
  match p of
    (x, y) => (y, x)

fn pair_map(f, g, p) =
  match p of
    (x, y) => (f(x), g(y))

fn optional(thunk) =
  handle thunk() with
    never fail() => None
    return r => Some(r)

fn forever(body) =
  body()
  forever(body)

fn run_io(action : (Unit) -> a ! {Console, FileSystem, Random, Entropy, Env, Output | e}) =
  handle (handle handle handle handle handle action(()) with {
      con_read_int() resume k => k(prim_read_int()),
      con_read_line() resume k => k(prim_read_line()),
      return r => r
    } with {
      fs_read_file(p) resume k => k(prim_read_file(p)),
      fs_read_bytes(p) resume k => k(prim_read_bytes(p)),
      fs_file_exists(p) resume k => k(prim_file_exists(p)),
      return r => r
    } with {
      rng_rand() resume k => k(prim_rand()),
      return r => r
    } with {
      entropy_word() resume k => k(prim_entropy()),
      return r => r
    } with {
      env_get(s) resume k => k(prim_getenv(s)),
      env_argc() resume k => k(prim_args_count()),
      env_arg(i) resume k => k(prim_arg(i)),
      return r => r
    }) with
    out_print(x) resume k =>
      prim_print(x)
      k(())
    out_println(x) resume k =>
      prim_println(x)
      k(())
    return r => r

fn stake_go(s, n) =
  let g =
    handle s(()) with
      emit(x) resume k =>
        \(left) -> if left > 0 then let _ = emit(x) in k(())(left - 1) else ()
      return r => \(_left) -> ()
  g(n)

fn sfold(s : (Unit) -> r ! {Emit(a) | e}, z, f) =
  let g =
    handle s(()) with
      emit(x) resume k => \(acc) -> k(())(f(acc, x))
      return r => \(acc) -> acc
  g(z)

fn hm_lookup(hm : HashMap(v), k : String) : Option(v) =
  let bs = hm.buckets
  assoc_get(array_get(bs, bucket_of(k, array_len(bs))), k)

fn hm_put_raw(hm : HashMap(v), k : String, x : v) : HashMap(v) =
  let bs = hm.buckets
  let i = bucket_of(k, array_len(bs))
  match assoc_put(array_get(bs, i), k, x) of
    (chain, added) =>
      HM { buckets = array_set(bs, i, chain), size = hm.size + added }

fn hm_insert(hm : HashMap(v), k : String, x : v) : HashMap(v) =
  let next = hm_put_raw(hm, k, x)
  if next.size > array_len(next.buckets) then
    hm_reinsert(
        HM { buckets = array_new(array_len(next.buckets) * 2, Nil), size = 0 },
        hm_to_list(next),
      )
  else
    next

fn hm_delete(hm : HashMap(v), k : String) : HashMap(v) =
  let bs = hm.buckets
  let i = bucket_of(k, array_len(bs))
  match assoc_del(array_get(bs, i), k) of
    (chain, removed) =>
      HM { buckets = array_set(bs, i, chain), size = hm.size - removed }

class Plate(a)
  children : (a) -> List(a)
  rebuild : (a, List(a)) -> a ! {Fail | e}

class Div(a)
  quotient : (a, a) -> a
  modulo : (a, a) -> a

class Foldable(t)
  fold_r : ((a, b) -> b ! {| e}, b, t(a)) -> b ! {| e}
  fold_l : ((b, a) -> b ! {| e}, b, t(a)) -> b ! {| e}

instance foldableList : Foldable(List)
  fn fold_r(g, z, xs) = foldr(g, z, xs)
  fn fold_l(g, z, xs) = foldl(g, z, xs)

instance foldableOption : Foldable(Option)
  fn fold_r(g, z, o) = option_fold_r(g, z, o)
  fn fold_l(g, z, o) = option_fold_l(g, z, o)

class Applicative(f) given Functor(f)
  pure : (a) -> f(a)
  ap : (f((a) -> b ! {| e}), f(a)) -> f(b) ! {| e}

instance applicativeList : Applicative(List)
  fn pure(x) = singleton(x)
  fn ap(fs, xs) = list_ap(fs, xs)

instance applicativeOption : Applicative(Option)
  fn pure(x) = Some(x)
  fn ap(fo, xo) = option_ap(fo, xo)

fn lay_collect(
  p : Layer(a),
  q : (a) -> Bool ! {| e},
  x : a
) : List(a) ! { | e} =
  filter(q, lay_universe(p, x))

fn lay_count_where(
  p : Layer(a),
  q : (a) -> Bool ! {| e},
  x : a
) : Int ! { | e} =
  length(lay_collect(p, q, x))

fn lay_index_where(
  p : Layer(a),
  q : (a) -> Bool ! {| e},
  x : a
) : List(Int) ! { | e} =
  lay_index_go(q, lay_universe(p, x), 0)

fn lay_edges(p : Layer(a), x : a) : List((a, a)) =
  let cs = lay_kids(p, x)
  append(map(\(c) -> (x, c), cs), concat_map(\(c) -> lay_edges(p, c), cs))

fn rw_repeat_go(
  s : Rewrite(a, e),
  fuel : Int,
  x : a,
  n : Int
) : RwFix(a) ! { | e} =
  match s(x) of
    None => RwFix { tree = x, steps = n, converged = true }
    Some(y) =>
      if n >= fuel then
        RwFix { tree = x, steps = n, converged = false }
      else
        rw_repeat_go(s, fuel, y, n + 1)

fn rw_lift_changed(
  f : (a) -> a ! {| e},
  same : (a, a) -> Bool ! {| e}
) : Rewrite(a, e) =
  \(x) -> rw_changed(same, x, f(x))

fn rw_steps_at(p : Layer(a), s : Rewrite(a, e), x : a) : List(a) ! { | e} =
  let here =
    match s(x) of
      Some(y) => [y]
      None => []
  append(here, rw_steps_kids(p, s, x, Nil, lay_kids(p, x)))

fn eval_state(init : s, action : () -> a ! {State(s) | e}) : a =
  match run_state(init, action) of
    (a, _s) => a

fn exec_state(init : s, action : () -> a ! {State(s) | e}) : s =
  match run_state(init, action) of
    (_a, s) => s

fn capture_validate(action : () -> a ! {Validate(e) | r}) : (Option(a), List(e)) =
  let f =
    handle action() with
      never refute(err) => \(errs) -> (None, reverse(Cons(err, errs)))
      dispute(err) resume k => \(errs) -> k(())(Cons(err, errs))
      return value => \(errs) -> (Some(value), reverse(errs))
  f(Nil)

fn eval_writer(action : () -> a ! {Writer(w) | e}) : a =
  match run_writer(action) of
    (r, _log) => r

fn exec_writer(action : () -> a ! {Writer(w) | e}) : List(w) =
  match run_writer(action) of
    (_r, log) => log

fn censor(
  f : (List(w)) -> List(w),
  action : () -> a ! {Writer(w) | e}
) : a ! {Writer(w) | e} =
  match run_writer(action) of
    (r, log) =>
      tells(f(log))
      r

fn bind_index_int(i : Index) : Int =
  match i of
    MkIndex(n) => n

fn bind_level_int(l : Level) : Int =
  match l of
    MkLevel(n) => n

fn bind_push_names(
  env : BindEnv(String),
  names : List(String)
) : BindEnv(String) =
  bind_push_all(env, map(\(n) -> (n, n), names))

fn bytes_to_string(bs : Bytes) : Option(String) =
  let b = bytes_buf(bs)
  if buf_utf8_valid(b) then
    Some(string_of_buf(b))
  else
    None

fn hex_decode(s : String) : Option(Bytes) =
  let n = byte_len(s)
  if not(mod(n, 2) == 0) then
    None
  else
    hex_decode_go(buf_empty(), s, 0, n)

fn hex_decode_go(acc : Buf, s : String, i : Int, n : Int) : Option(Bytes) =
  if i >= n then
    Some(bytes_of_buf(acc))
  else
    let hi = hex_value(byte_at(s, i))
    let lo = hex_value(byte_at(s, i + 1))
    if hi < 0 || lo < 0 then
      None
    else
      hex_decode_go(buf_push(acc, hi * hex_lo_mask + lo), s, i + 2, n)

fn base64_decode(s : String) : Option(Bytes) =
  let n = byte_len(s)
  if not(mod(n, 4) == 0) then
    None
  else
    base64_decode_go(buf_empty(), s, 0, n)

instance checkedI64 : Checked(I64)
  fn checked_add(x, y) = i64_check(int_of_i64(x) + int_of_i64(y))
  fn checked_sub(x, y) = i64_check(int_of_i64(x) - int_of_i64(y))
  fn checked_mul(x, y) = i64_check(int_of_i64(x) * int_of_i64(y))
  fn checked_neg(x) = i64_check(0 - int_of_i64(x))
  fn checked_div(x, y) =
    if i64_div_ok(x, y) then
      Some(x / y)
    else
      None
  fn checked_mod(x, y) =
    if i64_div_ok(x, y) then
      Some(x % y)
    else
      None
  fn saturating_add(x, y) = i64_clamp(int_of_i64(x) + int_of_i64(y))
  fn saturating_sub(x, y) = i64_clamp(int_of_i64(x) - int_of_i64(y))
  fn saturating_mul(x, y) = i64_clamp(int_of_i64(x) * int_of_i64(y))
  fn wrapping_add(x, y) = x + y
  fn wrapping_sub(x, y) = x - y
  fn wrapping_mul(x, y) = x * y
  fn wrapping_neg(x) = to_i64(0) - x
  fn overflowing_add(x, y) = i64_pair(int_of_i64(x) + int_of_i64(y))
  fn overflowing_sub(x, y) = i64_pair(int_of_i64(x) - int_of_i64(y))
  fn overflowing_mul(x, y) = i64_pair(int_of_i64(x) * int_of_i64(y))

instance checkedU64 : Checked(U64)
  fn checked_add(x, y) = u64_check(int_of_u64(x) + int_of_u64(y))
  fn checked_sub(x, y) = u64_check(int_of_u64(x) - int_of_u64(y))
  fn checked_mul(x, y) = u64_check(int_of_u64(x) * int_of_u64(y))
  fn checked_neg(x) =
    if x == to_u64(0) then
      Some(to_u64(0))
    else
      None
  fn checked_div(x, y) =
    if y == to_u64(0) then
      None
    else
      Some(x / y)
  fn checked_mod(x, y) =
    if y == to_u64(0) then
      None
    else
      Some(x % y)
  fn saturating_add(x, y) = u64_clamp(int_of_u64(x) + int_of_u64(y))
  fn saturating_sub(x, y) = u64_clamp(int_of_u64(x) - int_of_u64(y))
  fn saturating_mul(x, y) = u64_clamp(int_of_u64(x) * int_of_u64(y))
  fn wrapping_add(x, y) = x + y
  fn wrapping_sub(x, y) = x - y
  fn wrapping_mul(x, y) = x * y
  fn wrapping_neg(x) = to_u64(0) - x
  fn overflowing_add(x, y) = u64_pair(int_of_u64(x) + int_of_u64(y))
  fn overflowing_sub(x, y) = u64_pair(int_of_u64(x) - int_of_u64(y))
  fn overflowing_mul(x, y) = u64_pair(int_of_u64(x) * int_of_u64(y))

instance checkedInt : Checked(Int)
  fn checked_add(x, y) = Some(x + y)
  fn checked_sub(x, y) = Some(x - y)
  fn checked_mul(x, y) = Some(x * y)
  fn checked_neg(x) = Some(0 - x)
  fn checked_div(x, y) =
    if y == 0 then
      None
    else
      Some(x / y)
  fn checked_mod(x, y) =
    if y == 0 then
      None
    else
      Some(x % y)
  fn saturating_add(x, y) = x + y
  fn saturating_sub(x, y) = x - y
  fn saturating_mul(x, y) = x * y
  fn wrapping_add(x, y) = x + y
  fn wrapping_sub(x, y) = x - y
  fn wrapping_mul(x, y) = x * y
  fn wrapping_neg(x) = 0 - x
  fn overflowing_add(x, y) = (x + y, false)
  fn overflowing_sub(x, y) = (x - y, false)
  fn overflowing_mul(x, y) = (x * y, false)

instance latUnit : Semilattice(Unit)
  fn lat_bottom() = ()
  fn lat_join(_x, _y) = ()
  fn lat_leq(_x, _y) = true

instance latOption : Semilattice(Option(a)) given Semilattice(a)
  fn lat_bottom() = None
  fn lat_join(x, y) = lat_option_join(x, y)
  fn lat_leq(x, y) = lat_option_leq(x, y)

instance latPair : Semilattice((a, b)) given Semilattice(a), Semilattice(b)
  fn lat_bottom() = (lat_bottom(), lat_bottom())
  fn lat_join(x, y) = lat_pair_join(x, y)
  fn lat_leq(x, y) = lat_pair_leq(x, y)

fn lat_pair_join(
  x : (a, b),
  y : (a, b)
) : (a, b) given Semilattice(a), Semilattice(b) =
  match (x, y) of
    ((x1, x2), (y1, y2)) => (lat_join(x1, y1), lat_join(x2, y2))

fn lat_pair_leq(
  x : (a, b),
  y : (a, b)
) : Bool given Semilattice(a), Semilattice(b) =
  match (x, y) of
    ((x1, x2), (y1, y2)) => lat_leq(x1, y1) && lat_leq(x2, y2)

instance latMap : Semilattice(Map(k, v, ord)) given Ord(k), Semilattice(v)
  fn lat_bottom() = map_empty
  fn lat_join(x, y) = lat_map_join(x, y)
  fn lat_leq(x, y) = lat_map_leq(x, y)

fn lat_map_join(
  x : Map(k, v),
  y : Map(k, v)
) : Map(k, v) given Ord(k), Semilattice(v) =
  foldl(\(acc, p) -> lat_map_add(acc, p), x, map_to_list(y))

fn lat_map_leq(
  x : Map(k, v),
  y : Map(k, v)
) : Bool given Ord(k), Semilattice(v) =
  all(\(p) -> lat_map_entry_leq(p, y), map_to_list(x))

fn fix_budget(seed : Map(k, a), uses : Map(k, List(k))) : Int =
  let n = map_size(seed)
  let e = foldl(\(acc, ds) -> acc + length(ds), 0, map_values(uses))
  (n + 1) * (n + e + 1)

fn fix_least(
  seed : Map(k, a),
  uses : Map(k, List(k)),
  step : (k, Map(k, a)) -> a ! {| e}
) : Map(k, a) ! {Fail | e} given Ord(k), Semilattice(a) =
  fix_least_within(fix_budget(seed, uses), seed, uses, step)

fn fix_least_within(
  budget : Int,
  seed : Map(k, a),
  uses : Map(k, List(k)),
  step : (k, Map(k, a)) -> a ! {| e}
) : Map(k, a) ! {Fail | e} given Ord(k), Semilattice(a) =
  let start = map_keys(seed)
  let nodes = set_from_list(start)
  fix_go(fix_dependents(nodes, uses), step, (seed, start, nodes, budget))

fn fix_dependents(
  nodes : Map(k, Unit),
  uses : Map(k, List(k))
) : Map(k, List(k)) given Ord(k) =
  foldl(
      \(acc, key) -> fix_reverse_edges(acc, nodes, key, graph_successors(uses, key)),
      graph_empty,
      set_to_list(nodes),
    )

fn fix_propagate(
  own : Map(k, a),
  uses : Map(k, List(k))
) : Map(k, a) ! {Fail | e} given Ord(k), Semilattice(a) =
  let nodes =
    set_union(set_from_list(map_keys(own)), set_from_list(graph_nodes(uses)))
  let seed = foldl(
      \(acc, key) -> map_insert(key, fix_at(own, key), acc),
      map_empty,
      set_to_list(nodes),
    )
  fix_least(seed, uses) fn(key, cur)
    fix_gather(fix_at(own, key), cur, graph_successors(uses, key))

class FlatElem(a)
  fa_new : (Int, a) -> FlatArray(a)
  fa_get : (FlatArray(a), Int) -> a ! {Fail}
  fa_set : (FlatArray(a), Int, a) -> FlatArray(a) ! {Fail}

instance flatFloat : FlatElem(Float)
  fn fa_new(n, init) = FloatArr(tbuf_new(n, init))
  fn fa_get(xs, i) =
    match xs of
      FloatArr(b) => tbuf_get(b, i)
      IntArr(_) => fail()
  fn fa_set(xs, i, x) =
    match xs of
      FloatArr(b) => FloatArr(tbuf_set(b, i, x))
      IntArr(_) => fail()

instance flatI64 : FlatElem(I64)
  fn fa_new(n, init) = IntArr(ibuf_new(n, init))
  fn fa_get(xs, i) =
    match xs of
      IntArr(b) => ibuf_get(b, i)
      FloatArr(_) => fail()
  fn fa_set(xs, i, x) =
    match xs of
      IntArr(b) => IntArr(ibuf_set(b, i, x))
      FloatArr(_) => fail()

fn find(p : (a) -> Bool, t : f(a)) : Option(a) given Foldable(f) =
  fold_l(
      \(acc, x) -> if is_some(acc) then acc elif p(x) then Some(x) else None,
      None,
      t,
    )

fn fz_thaw(xs : Frozen(a)) : Array(a) =
  match xs of
    Frz(arr) => arr

fn fz_len(xs : Frozen(a)) : Int =
  match xs of
    Frz(arr) => array_len(arr)

fn fz_get(xs : Frozen(a), i : Int) : a ! {Fail} =
  match xs of
    Frz(arr) => at_array(arr, i)

fn fz_foldl(f, acc, xs) =
  match xs of
    Frz(arr) => array_foldl(f, acc, arr)

fn fz_to_list(xs : Frozen(a)) : List(a) =
  match xs of
    Frz(arr) => array_to_list(arr)

fn graph_add_edge(
  g : Map(k, List(k)),
  u : k,
  v : k
) : Map(k, List(k)) given Ord(k) =
  map_insert(u, insert_sorted_uniq(v, graph_successors(g, u)), g)

fn graph_from_edges(es : List((k, k))) : Map(k, List(k)) given Ord(k) =
  foldl(
      \(acc, e) -> match e of { (u, v) => graph_add_edge(acc, u, v) },
      graph_empty,
      es,
    )

fn graph_nodes(g : Map(k, List(k))) : List(k) given Ord(k) =
  let sources = set_from_list(map_keys(g))
  let all = foldl(
      \(acc, u) -> set_union(acc, set_from_list(graph_successors(g, u))),
      sources,
      map_keys(g),
    )
  set_to_list(all)

fn graph_reverse(g : Map(k, List(k))) : Map(k, List(k)) given Ord(k) =
  let seeded =
    foldl(\(acc, u) -> graph_add_node(acc, u), graph_empty, graph_nodes(g))
  foldl(
      \(acc, u) -> foldl(\(a, v) -> graph_add_edge(a, v, u), acc, graph_successors(g, u)),
      seeded,
      graph_nodes(g),
    )

fn graph_dfs(g : Map(k, List(k)), start : k) : List(k) given Ord(k) =
  match dfs_go(g, Cons(start, Nil), set_empty, Nil) of
    (_seen, acc) => reverse(acc)

fn graph_transitive_closure(g : Map(k, List(k))) : Map(k, List(k)) given Ord(k) =
  foldl(
      \(acc, u) -> foldl(\(a, v) -> graph_add_edge(a, u, v), acc, reachable_from_succ(g, u)),
      graph_empty,
      graph_nodes(g),
    )

fn reachable_from_succ(g : Map(k, List(k)), u : k) : List(k) given Ord(k) =
  set_to_list(
      foldl(
          \(acc, v) -> set_union(acc, set_from_list(graph_reachable(g, v))),
          set_empty,
          graph_successors(g, u),
        ),
    )

fn graph_topo_sort(g : Map(k, List(k))) : List(k) given Ord(k) =
  match (foldl(\(st, u) -> topo_visit(g, u, st), (set_empty, Nil), graph_nodes(g))) of
    (_seen, order) => order

fn graph_scc(g : Map(k, List(k))) : List(List(k)) given Ord(k) =
  match (foldl(\(st, u) -> scc_start(g, u, st), scc_init(), graph_nodes(g))) of
    (_meta, _on, _cstk, _next, sccs, _work) => reverse(sccs)

fn im_high_bit(x : U64) : U64 =
  let a = u64_or(x, u64_shr(x, 1u64))
  let b = u64_or(a, u64_shr(a, 2u64))
  let c = u64_or(b, u64_shr(b, 4u64))
  let d = u64_or(c, u64_shr(c, 8u64))
  let e = u64_or(d, u64_shr(d, 16u64))
  let f = u64_or(e, u64_shr(e, 32u64))
  f - u64_shr(f, 1u64)

fn im_link(w1 : U64, t1 : IntMap(v), w2 : U64, t2 : IntMap(v)) : IntMap(v) =
  let m = im_high_bit(u64_xor(w1, w2))
  let p = im_prefix(w1, m)
  if im_zero(w1, m) then
    IMBranch(p, m, t1, t2)
  else
    IMBranch(p, m, t2, t1)

fn intmap_from_list(xs : List((I64, v))) : IntMap(v) =
  foldl(
      \(acc, p) -> match p of { (k, v) => intmap_insert(k, v, acc) },
      intmap_empty,
      xs,
    )

fn unzip(ps) =
  (
      map(\(p) -> match p of { (x, _) => x }, ps),
      map(\(p) -> match p of { (_, y) => y }, ps),
    )

fn scan_left(f, z, xs) =
  Cons(
      z,
      match xs of { Nil => Nil, Cons(x, rest) => scan_left(f, f(z, x), rest) },
    )

fn map_from_list(xs : List((k, v))) : Map(k, v) given Ord(k) =
  foldl(
      \(acc, p) -> match p of { (ka, va) => map_insert(ka, va, acc) },
      Tip,
      xs,
    )

