fn pad_left(s, w) =
  let pad = w - str_len(s)
  if pad <= 0 then
    s
  else
    concat(str_repeat(" ", pad), s)

fn pad_right(s, w) =
  let pad = w - str_len(s)
  if pad <= 0 then
    s
  else
    concat(s, str_repeat(" ", pad))

fn ends_with(suffix : String, s : String) : Bool =
  let d = byte_len(s) - byte_len(suffix)
  if d < 0 then
    false
  else
    occurs_at(suffix, s, d, 0)

fn trim(s : String) : String =
  let lo = ltrim_idx(s, 0)
  let hi = rtrim_idx(s, byte_len(s))
  if lo >= hi then
    ""
  else
    string_of_buf(slice_bytes(s, lo, hi, buf_empty()))

fn split_from(c, s, i) =
  let j = index_of_from(c, s, i)
  if j < 0 then
    Cons(substring(s, i, str_len(s) - i), Nil)
  else
    Cons(substring(s, i, j - i), split_from(c, s, j + 1))

fn buf(t : Tensor) : FloatBuf =
  match t of
    MkTensor(b, _, _, _) => b

fn shape(t : Tensor) : List(Int) =
  match t of
    MkTensor(_, s, _, _) => s

fn strides(t : Tensor) : List(Int) =
  match t of
    MkTensor(_, _, st, _) => st

fn axes(t : Tensor) : List(String) =
  match t of
    MkTensor(_, _, _, ax) => ax

fn transpose(t : Tensor, a : String, b : String) : Tensor =
  match t of
    MkTensor(b0, sh, st, ax) =>
      let i = index_of(a, ax)
      let j = index_of(b, ax)
      MkTensor(b0, swap_at(i, j, sh), swap_at(i, j, st), swap_at(i, j, ax))

fn is_contig(t : Tensor) : Bool =
  match t of
    MkTensor(_, sh, st, _) => st == rm_strides(sh)

fn map_tensor(f, t : Tensor) : Tensor ! {Fail} =
  if is_contig(t) then
    let sh = shape(t)
    contig_tensor(sh, map_fill(f, buf(t), tbuf_new(prod(sh), 0.0), 0, prod(sh)))
  else
    fail()

fn zip_with_tensor(f, a : Tensor, b : Tensor) : Tensor ! {Fail} =
  let sh = shape(a)
  if sh == shape(b) && is_contig(a) && is_contig(b) then
    contig_tensor(
        sh,
        zip_fill(f, buf(a), buf(b), tbuf_new(prod(sh), 0.0), 0, prod(sh)),
      )
  else
    fail()

fn sum_axis(t : Tensor, axis_name : String) : Tensor ! {Fail} =
  if is_contig(t) then
    let sh = shape(t)
    let st = strides(t)
    let ax = axes(t)
    let a = index_of(axis_name, ax)
    let extent = at_or_fail(a, sh)
    let sa = at_or_fail(a, st)
    let osh = drop_at(a, sh)
    let oax = drop_at(a, ax)
    let ks = drop_at(a, st)
    let ostrides = rm_strides(osh)
    let total = prod(osh)
    MkTensor(
        sum_axis_fill(
            buf(t),
            tbuf_new(total, 0.0),
            ostrides,
            osh,
            ks,
            sa,
            extent,
            0,
            total,
          ),
        osh,
        ostrides,
        oax,
      )
  else
    fail()

fn mean_axis(t : Tensor, axis_name : String) : Tensor ! {Fail} =
  let extent = at_or_fail(index_of(axis_name, axes(t)), shape(t))
  scale(1.0 / to_float(extent), sum_axis(t, axis_name))

fn uf_union(uf : Map(k, k), x : k, y : k) : Map(k, k) given Ord(k) =
  let rx = uf_find(uf, x)
  let ry = uf_find(uf, y)
  let c = cmp(rx, ry)
  if c == 0 then
    uf
  elif c < 0 then
    map_insert(ry, rx, uf)
  else
    map_insert(rx, ry, uf)

fn ufp_set(
  uf : UnionFind(k, a),
  x : k,
  a : a
) : Result(UnionFind(k, a), UfError) given Ord(k) =
  if member(uf, x) then
    let r = root_of(uf, x)
    Ok(Ufp { ..uf, payloads = map_insert(r, a, uf.payloads) })
  else
    Err(UfAbsent)

fn ufp_union_with(
  combine : (a, a) -> a ! {| e},
  uf : UnionFind(k, a),
  x : k,
  y : k
) : Result(UnionFind(k, a), UfError) ! { | e} given Ord(k) =
  if not(member(uf, x)) || not(member(uf, y)) then
    Err(UfAbsent)
  else
    let rx = root_of(uf, x)
    let ry = root_of(uf, y)
    let c = cmp(rx, ry)
    if c == 0 then
      Ok(uf)
    else
      let kept =
        if c < 0 then
          rx
        else
          ry
      let lost =
        if c < 0 then
          ry
        else
          rx
      match ((map_lookup(kept, uf.payloads), map_lookup(lost, uf.payloads))) of
        (Some(ka), Some(la)) =>
          let joined = combine(ka, la)
          Ok(
              Ufp {
                parents = map_insert(lost, kept, uf.parents),
                payloads = map_insert(kept, joined, map_delete(lost, uf.payloads))
              },
            )
        _ => Err(UfAbsent)

