fn cursor_of(ts : List(Token), stop : Int) : Cursor =
  Cursor {
    toks = array_of_list(ts),
    pos = 0,
    stop = stop,
    far = 0,
    wanted = Nil
  }

fn cursor_advance(c : Cursor) : Cursor =
  if cursor_at_end(c) then
    c
  else
    Cursor { ..c, pos = c.pos + 1 }

fn cursor_note_name(c : Cursor, name : String) : Cursor =
  if c.pos > c.far then
    Cursor { ..c, far = c.pos, wanted = [name] }
  elif c.pos == c.far then
    Cursor { ..c, wanted = add_name(c.wanted, name) }
  else
    c

fn cursor_message(c : Cursor) : String =
  let found = found_name(c)
  match c.wanted of
    Nil => "unexpected {found}"
    Cons(x, rest) =>
      match rest of
        Nil => "expected {x}, found {found}"
        Cons(_, _) =>
          let all = str_join(", ", c.wanted)
          "expected one of {all}, found {found}"

fn cursor_diagnostic(c : Cursor) : Diagnostic =
  Diagnostic {
    code = cursor_code(c),
    phase = DPParse,
    span = cursor_far_span(c),
    message = cursor_message(c),
    expected = cursor_canonical(c),
    related = Nil
  }

