fn ed_insert_at(offset : Int, text : String) : Edit =
  Edit {
    span = Span { lo = offset, hi = offset },
    text = text
  }

fn fl_calls(doc : ResolvedDoc) : Map(String, List(String)) =
  let defined = fl_defined(doc)
  foldl(
      \(g, f) -> fl_edges(g, doc.source, defined, f),
      graph_empty,
      doc.functions,
    )

fn fl_direct(g : Map(k, List(k))) : Map(k, Map(k, Unit)) given Ord(k) =
  foldl(
      \(acc, key) -> map_insert(key, set_from_list(graph_successors(g, key)), acc),
      map_empty,
      map_keys(g),
    )

fn fl_transitive(doc : ResolvedDoc) : Map(String, Map(String, Unit)) ! {Fail | e} =
  let calls = fl_calls(doc)
  fix_propagate(fl_direct(calls), calls)

fn fl_live(
  doc : ResolvedDoc,
  roots : List(String)
) : Map(String, Unit) ! {Fail | e} =
  let calls = fl_calls(doc)
  let seeds = foldl(
      \(acc, key) -> map_insert(key, elem(key, roots), acc),
      map_empty,
      map_keys(calls),
    )
  fl_reached(fix_propagate(seeds, graph_reverse(calls)))

fn fl_dead(
  doc : ResolvedDoc,
  roots : List(String)
) : List(String) ! {Fail | e} =
  let live = fl_live(doc, roots)
  filter(\(name) -> not(set_member(name, live)), set_to_list(fl_defined(doc)))

fn fl_recursive(doc : ResolvedDoc) : List(String) ! {Fail | e} =
  let reach = fl_transitive(doc)
  filter(\(name) -> set_member(name, fix_at(reach, name)), map_keys(reach))

fn surface_identity(d : SurfaceDoc) : Result(String, JsonError) =
  map_result(
      \(j) -> canonical_json(surface_subject(j)),
      decode(encode_surface(d)),
    )

fn is_subject_field(kv : (String, Json)) : Bool =
  match kv of
    (k, _) => k == "schema" || k == "items"

fn is_position_field(kv : (String, Json)) : Bool =
  match kv of
    (k, _) => not(k == "span")

fn ly_virt(k : TokenKind, off : Int) : Token =
  Token {
    kind = k,
    span = Span { lo = off, hi = off },
    value = None
  }

fn ly_head_run(
  text : String,
  toks : List(Token),
  endoff : Int,
  acc : List(LEntry)
) : HeadR =
  match toks of
    Nil => HeadR { rest = Nil, endoff = endoff, acc = acc }
    Cons(t, rest) =>
      if ly_same_line(text, endoff, t.span.lo) then
        ly_head_run(text, rest, t.span.hi, Cons(LTok(t), acc))
      else
        HeadR { rest = toks, endoff = endoff, acc = acc }

fn ly_close_loop(
  stack : List(Int),
  col : Int,
  last_hi : Int,
  out : List(Token)
) : CloseR =
  match ly_stack_step(stack, col, 1) of
    CPop =>
      ly_close_loop(ly_pop(stack), col, last_hi, Cons(ly_vclose(last_hi), out))
    CSep => CloseR { stack = stack, out = Cons(ly_vsep(last_hi), out) }
    CNone => CloseR { stack = stack, out = out }

fn ly_phase2(
  bopen : Bool,
  bclose : Bool,
  depth : Int,
  po : Bool,
  carry : Bool
) : Ph2R =
  if bopen then
    Ph2R { depth = depth + 1, po = po, carry = carry }
  elif bclose then
    let d2 =
      if depth > 0 then
        depth - 1
      else
        0
    if d2 == 0 && carry then
      Ph2R { depth = d2, po = true, carry = false }
    else
      Ph2R { depth = d2, po = po, carry = carry }
  else
    Ph2R { depth = depth, po = po, carry = carry }

fn ly_step(text : String, e : LEntry, st : LState, out : List(Token)) : StepR =
  let lo = ly_e_lo(e)
  let hi = ly_e_hi(e)
  let col = ly_col(text, lo)
  let cur_line = ly_prev_line(st) + ly_count_nl(text, st.prev_off, lo)
  let new_line = ly_is_newline(st.prev_line, cur_line)
  let in_brackets = st.bracket_depth > 0
  let bopen = ly_e_bopen(e)
  let bclose = ly_e_bclose(e)
  match ly_phase1(e, st, lo, col, new_line, in_brackets, bopen, out) of
    Ph1R { stack = stack1, out = out1, po = po1, carry = carry1 } =>
      match ly_phase2(bopen, bclose, st.bracket_depth, po1, carry1) of
        Ph2R { depth = depth2, po = po2, carry = carry2 } =>
          let out3 =
            match e of
              LHead(_) => out1
              LTok(t) => Cons(t, out1)
          let ploff =
            if hi > lo then
              hi - 1
            else
              lo
          let st2 =
            LState {
              stack = stack1,
              pending_opener = po2,
              carrying = carry2,
              bracket_depth = depth2,
              prev_line = Some(cur_line + ly_count_nl(text, lo, ploff)),
              prev_off = ploff,
              last_hi = hi
            }
          StepR(st2, out3)

fn ly_layout(text : String, toks : List(Token)) : List(Token) =
  let entries = ly_inject(text, toks)
  let st0 =
    LState {
      stack = Nil,
      pending_opener = false,
      carrying = false,
      bracket_depth = 0,
      prev_line = None,
      prev_off = 0,
      last_hi = 0
    }
  ly_run(text, entries, st0, Nil)

fn lx_skip_cp(text : String, p : Int, n : Int) : Int =
  let b = lx_at(text, p)
  if b == lx_eof() then
    p
  else
    p + lx_cp_len(b)

type LxTabs = LxTabs {
  lower: Array(List(String)),
  upper: Array(List(String)),
  ops: Array(List(String))
}

fn lx_tabs() : LxTabs =
  LxTabs {
    lower = lx_by_first(lx_lower_keywords()),
    upper = lx_by_first(lx_upper_keywords()),
    ops = lx_by_first(lx_operators())
  }

fn lx_by_first_go(
  xs : List(String),
  acc : Array(List(String))
) : Array(List(String)) =
  match xs of
    Nil => acc
    Cons(s, rest) =>
      let b = byte_at(s, 0)
      lx_by_first_go(rest, array_set(acc, b, Cons(s, array_get(acc, b))))

fn lx_lower(text : String, i : Int, n : Int, kws : List(String)) : LxStep =
  let j = lx_scan_word(text, i, n)
  match lx_find_kw(text, i, j, kws) of
    Some(kw) => LxTok(TFixed(kw), j)
    None => LxTok(TIdent, j)

fn lx_sep_flanked(text : String, k : Int, lo : Int, hi : Int) : Bool =
  let left = k > lo && is_digit(byte_at(text, k - 1))
  let right = k + 1 < hi && is_digit(byte_at(text, k + 1))
  left && right

fn lx_number_raw(text : String, i : Int, n : Int) : LxStep =
  let j = lx_scan_digits(text, i, n)
  if lx_at(text, j) == lx_b(".") && lx_digit_us(lx_at(text, j + 1)) then
    let k = lx_scan_digits(text, j + 1, n)
    LxTok(TFloat, lx_scan_exp(text, k, n))
  else
    let e = lx_scan_exp(text, j, n)
    if e > j then
      LxTok(TFloat, e)
    else
      lx_int_suffix(text, j)

fn lx_raw_from(text : String, lo : Int, hi : Int) : Int =
  let p = lx_skip_h(text, lo, hi)
  if p < hi && byte_at(text, p) == 10 then
    p + 1
  else
    lo

fn lx_raw_upto(text : String, lo : Int, hi : Int) : Int =
  let e = lx_trim_h(text, lo, hi)
  if e > lo && byte_at(text, e - 1) == 10 then
    e - 1
  else
    hi

fn lx_raw_cook(text : String, lo : Int, hi : Int) : String =
  let from = lx_raw_from(text, lo, hi)
  let upto = lx_raw_upto(text, from, hi)
  let ml =
    match lx_margin(text, from, upto, None) of
      None => 0
      Some(m) =>
        let (_, k) = m
        k
  string_of_buf(lx_raw_lines(text, from, upto, ml, true, buf_empty()))

fn lx_float_value(text : String, lo : Int, hi : Int) : String =
  show_float(
      parse_float(string_of_buf(lx_push_nonus(text, lo, hi, buf_empty()))),
    )

fn lx_interp(
  text : String,
  oq : Int,
  endq : Int
) : Result(List(Token), LexError) =
  lx_interp_go(text, oq + 1, endq - 1, endq, buf_empty(), oq, true, Nil)

fn authored(node : a, lo : Int, hi : Int) : Sp(a) =
  Sp {
    node = node,
    span = Span { lo = lo, hi = hi },
    synth = false
  }

fn synthesized(node : a, lo : Int, hi : Int) : Sp(a) =
  Sp {
    node = node,
    span = Span { lo = lo, hi = hi },
    synth = true
  }

fn zero_width(node : a, at : Int) : Sp(a) =
  Sp {
    node = node,
    span = Span { lo = at, hi = at },
    synth = false
  }

fn widened(x : Sp(a), lo : Int, hi : Int) : Sp(a) =
  Sp {
    node = x.node,
    span = Span { lo = lo, hi = hi },
    synth = x.synth
  }

fn note_fn_mod_follow(
  c : Cursor,
  allow_ident : Bool,
  allow_deprecation_string : Bool
) : Cursor =
  let c1 =
    if allow_ident then
      cursor_note(c, TIdent)
    else
      c
  let c2 =
    if allow_deprecation_string then
      cursor_note(c1, TStr)
    else
      c1
  let c3 = cursor_note(c2, TFixed("replayable"))
  let c4 = cursor_note(c3, TFixed("fip"))
  let c5 = cursor_note(c4, TFixed("fbip"))
  cursor_note(c5, TFixed("fn"))

fn cap_cursor(c : Cursor, stop : Int) : Cursor =
  let toks = take(stop, array_to_list(c.toks))
  let end_span =
    match cursor_peek_at(c, stop - c.pos) of
      None => c.stop
      Some(t) => t.span.lo
  Cursor {
    toks = array_of_list(toks),
    pos = c.pos,
    stop = end_span,
    far = min(c.far, stop),
    wanted = c.wanted
  }

fn note_stable_entry(c : Cursor) : Cursor =
  let c1 = cursor_note(c, TUid)
  let c2 = cursor_note_name(c1, "upgrade")
  let c3 = cursor_note_name(c2, "downgrade")
  cursor_note_name(c3, "migrations")

fn made(saved : Cursor, c : Cursor, node : Expr) : Sp(Expr) =
  let s = cursor_since(saved, c)
  authored(node, s.lo, s.hi)

fn remade(saved : Cursor, c : Cursor, node : Expr) : Sp(Expr) =
  let s = cursor_since(saved, c)
  synthesized(node, s.lo, s.hi)

fn note_expr(c : Cursor) : Cursor =
  let c1 = cursor_note(c, TIdent)
  let c2 = cursor_note(c1, TUid)
  let c3 = cursor_note(c2, TQual)
  let c4 = cursor_note(c3, TInt)
  let c5 = cursor_note(c4, TFloat)
  let c6 = cursor_note(c5, TChar)
  let c7 = cursor_note(c6, TStr)
  let c8 = cursor_note(c7, TFixed("("))
  let c9 = cursor_note(c8, TFixed("["))
  cursor_note(c9, TFixed("if"))

fn parse_uid_atom(c : Cursor, depth : Int) : Parsed(Sp(Expr)) =
  match cursor_peek(c) of
    None => PStuck(cursor_note(c, TUid))
    Some(t) =>
      let name = token_text(t)
      let c1 = cursor_advance(c)
      if at_fixed(c1, "\{") then
        parse_record_atom(c, name, c1, depth)
      else
        PTook(made(c, c1, EVar(name)), c1)

fn parse_interp_hole(
  saved : Cursor,
  c : Cursor,
  depth : Int,
  acc : List(Sp(Expr))
) : Parsed(Sp(Expr)) =
  match parse_expr(c, depth) of
    PStuck(c1) => PStuck(c1)
    PFault(d) => PFault(d)
    PTook(hole, c1) =>
      let with_hole = append(acc, [hole])
      match cursor_peek(c1) of
        None => PStuck(cursor_note(c1, TIEnd))
        Some(seg) =>
          if seg.kind == TIMid then
            let part = zero_width(EStr(token_text(seg)), cursor_span(saved).lo)
            parse_interp_hole(saved, cursor_advance(c1), depth, append(with_hole, [
                part,
              ]))
          elif seg.kind == TIEnd then
            let last = zero_width(EStr(token_text(seg)), cursor_span(saved).lo)
            let c2 = cursor_advance(c1)
            let marker = zero_width(EMarker("interp"), cursor_span(saved).lo)
            PTook(made(saved, c2, ECall(marker, append(with_hole, [last]))), c2)
          else
            let noted = cursor_note(cursor_note(c1, TIMid), TIEnd)
            PStuck(noted)

fn parse_error_call(c : Cursor, depth : Int) : Parsed(Sp(Expr)) =
  let c1 = cursor_advance(c)
  if at_fixed(c1, "(") then
    let callee = authored(EVar("error"), cursor_span(c).lo, cursor_span(c).hi)
    parse_call_tail(callee, c1, depth)
  else
    PStuck(cursor_note(c1, TFixed("(")))

fn build_compound(
  saved : Cursor,
  lhs : Sp(Expr),
  op : String,
  value : Sp(Expr),
  c : Cursor
) : Parsed(Sp(Expr)) =
  let span = cursor_since(saved, c)
  match lhs.node of
    EVar(name) =>
      let read = authored(EVar(name), span.lo, span.hi)
      let rhs = synthesized(EBin(op, read, value), span.lo, span.hi)
      PTook(authored(EAssign(name, rhs), span.lo, span.hi), c)
    EIndex(recv, key) =>
      let read = synthesized(EIndex(recv, key), span.lo, span.hi)
      let rhs = synthesized(EBin(op, read, value), span.lo, span.hi)
      PTook(authored(EIndexAssign(recv, key, rhs), span.lo, span.hi), c)
    _ =>
      PFault(
          refuse(
              lhs.span,
              "the left side of a compound assignment must be a variable or an index `a[i]`",
            ),
        )

fn widen_if_chain(e : Sp(Expr), lo : Int) : Sp(Expr) =
  match e.node of
    EIf(cond, yes, no) =>
      Sp {
        node = EIf(cond, yes, widen_if_chain(no, lo)),
        span = Span { lo = lo, hi = e.span.hi },
        synth = e.synth
      }
    _ => e

fn build_try_stmt(
  binder : Option(Sp(Pat)),
  scrutinee : Sp(Expr),
  rest : Sp(Expr),
  lo : Int
) : Sp(Expr) =
  let span = scrutinee.span
  let ok_value =
    match binder of
      None => authored(PWild, span.lo, span.hi)
      Some(pat) => pat
  let ok = authored(PCtor("Ok", [ok_value]), span.lo, span.hi)
  let err_value = authored(PVar("e@"), span.lo, span.hi)
  let err = authored(PCtor("Err", [err_value]), span.lo, span.hi)
  let err_ctor = authored(EVar("Err"), span.lo, span.hi)
  let err_var = authored(EVar("e@"), span.lo, span.hi)
  let rethrow = authored(ECall(err_ctor, [err_var]), span.lo, span.hi)
  let arms = [
      Arm { pat = ok, guard = None, body = rest },
      Arm { pat = err, guard = None, body = rethrow },
    ]
  synthesized(EMatch(scrutinee, arms), lo, lo)

fn parse_with_rest(saved : Cursor, c : Cursor, depth : Int) : Parsed(Sp(Expr)) =
  if at_kind(c, TVSemi) then
    parse_stmts(cursor_advance(c), depth)
  else
    let s = cursor_since(saved, c)
    PTook(authored(EMarker("with"), s.lo, s.hi), c)

fn generated_merge_cursor(at : Cursor, left : Cursor, right : Cursor) : Cursor =
  if left.far > right.far then
    Cursor { ..at, far = left.far, wanted = left.wanted }
  elif right.far > left.far then
    Cursor { ..at, far = right.far, wanted = right.wanted }
  else
    let noted =
      foldl(cursor_note_name, Cursor { ..left, pos = left.far }, right.wanted)
    Cursor { ..at, far = noted.far, wanted = noted.wanted }

