fn generated_record_field(
  c : Cursor,
  depth : Int
) : Parsed(GeneratedFieldDone) =
  match take_word(c, TIdent) of
    PStuck(c1) => PStuck(c1)
    PFault(d) => PFault(d)
    PTook(name, c1) =>
      if at_fixed(c1, "=") then
        generated_bind(generated_parse_pattern(cursor_advance(c1), depth)) fn(done, c2)
          PTook(
              FieldDone(
                  PatField { name = name, pat = pattern_value(done) },
                  GFExplicit(pattern_receipt(done)),
                ),
              c2,
            )
      else
        let span = cursor_since(c, c1)
        PTook(
            FieldDone(
                PatField {
                  name = name,
                  pat = authored(PVar(name), span.lo, span.hi)
                },
                GFShorthand,
              ),
            c1,
          )

